/**
 * n8n Code Node
 * Mode: Run Once for All Items
 * Purpose: Parse and clean up to 50 student records
 */

const inputItems = $input.all();
const MAX_RECORDS = 51;

const fields = [
  "Student_ID",
  "Name",
  "Email",
  "Phone",
  "Course",
  "Fee_Paid",
  "City",
  "Enrolled_Date",
  "Email_Valid"
];

// Convert common LLM boolean representations to real booleans
function toBoolean(value) {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value !== 0;

  if (typeof value === "string") {
    const v = value.trim().toLowerCase();
    if (["true", "yes", "1"].includes(v)) return true;
    if (["false", "no", "0"].includes(v)) return false;
  }

  return null;
}

// Parse JSON from plain text or Markdown code fences
function parseResponse(value) {
  if (value && typeof value === "object") {
    return value;
  }

  let text = String(value ?? "").trim();

  // Remove ```json and ``` fences
  text = text
    .replace(/^\s*```(?:json)?\s*/i, "")
    .replace(/\s*```\s*$/i, "")
    .trim();

  try {
    return JSON.parse(text);
  } catch (error) {
    // Try extracting a JSON array or object from extra LLM text
    const startArray = text.indexOf("[");
    const startObject = text.indexOf("{");

    let start;
    if (startArray === -1) start = startObject;
    else if (startObject === -1) start = startArray;
    else start = Math.min(startArray, startObject);

    const end = Math.max(
      text.lastIndexOf("]"),
      text.lastIndexOf("}")
    );

    if (start !== -1 && end > start) {
      return JSON.parse(text.slice(start, end + 1));
    }

    throw new Error("Could not parse valid JSON");
  }
}

// Locate the LLM response in the incoming n8n item
function getResponse(item) {
  const j = item.json;

  if (typeof j === "string") return j;

  for (const key of ["output", "text", "response", "content"]) {
    if (j[key] !== undefined) return j[key];
  }

  // The item itself may already be a student object
  return j;
}

// Normalize each student record
function cleanStudent(record) {
  const cleaned = {};

  for (const field of fields) {
    let value = record[field];

    if (typeof value === "string") {
      value = value.trim();
    }

    if (value === "" || value === undefined) {
      value = null;
    }

    cleaned[field] = value;
  }

  // Normalize text fields
  for (const field of [
    "Student_ID",
    "Name",
    "Course",
    "City"
  ]) {
    if (cleaned[field] !== null) {
      cleaned[field] = String(cleaned[field]).trim();
    }
  }

  // Normalize email
  if (cleaned.Email !== null) {
    cleaned.Email = String(cleaned.Email)
      .trim()
      .toLowerCase();
  }

  // Keep phone numbers as strings to preserve leading zeros
  if (cleaned.Phone !== null) {
    cleaned.Phone = String(cleaned.Phone).trim();
  }

  // Convert booleans correctly
  cleaned.Fee_Paid = toBoolean(cleaned.Fee_Paid);
  cleaned.Email_Valid = toBoolean(cleaned.Email_Valid);

  // Validate the date format (YYYY-MM-DD)
  if (cleaned.Enrolled_Date !== null) {
    const date = String(cleaned.Enrolled_Date).trim();

    cleaned.Enrolled_Date =
      /^\d{4}-\d{2}-\d{2}$/.test(date) &&
      !Number.isNaN(Date.parse(date))
        ? date
        : null;
  }

  return cleaned;
}

// Process the incoming responses
const students = [];
const errors = [];

for (let i = 0; i < inputItems.length; i++) {
  if (students.length >= MAX_RECORDS) break;

  try {
    const parsed = parseResponse(getResponse(inputItems[i]));

    const records = Array.isArray(parsed) ? parsed : [parsed];

    for (const record of records) {
      if (students.length >= MAX_RECORDS) break;

      if (
        !record ||
        typeof record !== "object" ||
        Array.isArray(record)
      ) {
        continue;
      }

      students.push(cleanStudent(record));
    }
  } catch (error) {
    errors.push({
      inputItem: i,
      message: error.message
    });
  }
}

// Return one n8n item per student
return students.map(student => ({
  json: student
}));
